-- ============================================================================
-- HELD DECISIONS (HD), typed "your case" panel mode: nodal.
--
-- Held decision: nodal intermediate lift gas fields had no route (W2 left them
-- for a W4 panel mode that no wave built). Owner approved the lead
-- recommendation 2026-09-22: add a typed-case panel mode (audit
-- recommendation: editable column inputs, six-decimal print clears the 7.6e-4
-- tol).
--
-- Plan of record: docs/graded-field-audit/FOLLOW-ON-PROGRAMME.md section 1,
-- route (b), and decision D2 (a panel may reach the capstone case when the
-- learner types it; no panel DEFAULT state lands on a graded answer). The
-- panel ships with the NextGen zip; this file adds one sentence to the brief
-- saying where the case can be typed. It joins the W2-W6 batch and applies
-- after every file in it.
--
-- INTERMEDIATE (2 graded field(s) now read in a typed panel mode:
-- liftgas_mid_pmf_psia, liftgas_valve_pwf_psia)
--   POINTER appended: On the course panel, the Outflow explorer's "Your gas
--   column, typed" view takes this injection column as typed (gravity, tubing
--   head pressure, both depths, both temperatures and the step count) and prints
--   the pressures at the bottom of the column (the valve depth) and at its
--   midpoint station to six decimals.
--
-- WHAT DOES NOT MOVE. `fields` (every key, label, unit, expected and
-- tolerance), title, dataset, status and the row. The guard requires `fields`
-- to equal its live value exactly, before and after, so no answer grades
-- differently and no attempts guard is needed.
--
-- GUARDS. Each prompt must hold its post-W2-W6 text (md5, rewritten) or its HD
-- text (left alone). Anything else raises and the file rolls back. A file that
-- will write first checks the W2-W6 post-state and refuses without it.
-- Generated by docs/graded-field-audit/hd_typed_capstones.py from
-- hd/nodal.json. SAFE TO RE-RUN: a second run writes nothing.
-- ============================================================================

do $$
declare
  v_n        integer;
  v_count    integer;
  v_written  integer := 0;
  v_s0       text;
begin
  -- nodal / intermediate
  select count(*) into v_n from public.academy_capstones where app_slug = 'nodal' and tier = 'intermediate' and active;
  if v_n <> 1 then raise exception 'hd nodal refused: nodal/intermediate has % active capstone rows, expected 1', v_n; end if;
  select case when md5(prompt) = '43e9b4136348adc42dd5053de84d8367' and fields = '[{"key": "vlp_min_q_stbd", "tol": 0.00064, "unit": "stb/d", "label": "Rate at the curve minimum", "expected": 1285.2338376891341}, {"key": "vlp_min_bhp_psia", "tol": 0.0014, "unit": "psia", "label": "Pressure at the minimum", "expected": 2849.67283735105}, {"key": "vlp_loaded_end_bhp_psia", "tol": 0.0025, "unit": "psia", "label": "Low rate end", "expected": 5046.565087663264}, {"key": "vlp_friction_end_bhp_psia", "tol": 0.0026, "unit": "psia", "label": "Open flow end", "expected": 5277.411341029544}, {"key": "liftgas_valve_pwf_psia", "tol": 0.00076, "unit": "psia", "label": "Injection pressure at depth", "expected": 1516.5314295864096}, {"key": "liftgas_mid_pmf_psia", "tol": 0.00069, "unit": "psia", "label": "Injection pressure at midpoint", "expected": 1373.724371881081}]'::jsonb then 'old'
              when md5(prompt) = 'ac000b3efdcbacb24b57d5f0ea1c3639' and fields = '[{"key": "vlp_min_q_stbd", "tol": 0.00064, "unit": "stb/d", "label": "Rate at the curve minimum", "expected": 1285.2338376891341}, {"key": "vlp_min_bhp_psia", "tol": 0.0014, "unit": "psia", "label": "Pressure at the minimum", "expected": 2849.67283735105}, {"key": "vlp_loaded_end_bhp_psia", "tol": 0.0025, "unit": "psia", "label": "Low rate end", "expected": 5046.565087663264}, {"key": "vlp_friction_end_bhp_psia", "tol": 0.0026, "unit": "psia", "label": "Open flow end", "expected": 5277.411341029544}, {"key": "liftgas_valve_pwf_psia", "tol": 0.00076, "unit": "psia", "label": "Injection pressure at depth", "expected": 1516.5314295864096}, {"key": "liftgas_mid_pmf_psia", "tol": 0.00069, "unit": "psia", "label": "Injection pressure at midpoint", "expected": 1373.724371881081}]'::jsonb then 'new'
              else 'other' end
    into v_s0 from public.academy_capstones where app_slug = 'nodal' and tier = 'intermediate' and active;
  if v_s0 = 'other' then
    raise exception 'hd nodal refused: nodal/intermediate matches neither its post-W2-W6 form (prompt md5 43e9b4136348adc42dd5053de84d8367) nor its HD form (prompt md5 ac000b3efdcbacb24b57d5f0ea1c3639), with the fields this file was generated against';
  end if;

  -- nothing to write: every row is already in its HD form
  if v_s0 = 'new' then
    raise notice 'hd nodal: 0 of 1 row(s) written, all already applied';
    return;
  end if;

  -- the W2-W6 batch (/root/w2w6-apply) must be applied first: its post-state is this file's base
  if not exists (select 1 from public.academy_capstones c, lateral jsonb_array_elements(c.fields) f
                  where c.app_slug = 'mbal' and c.tier = 'advanced' and c.active and f->>'key' = 'a111_ddi')
     or not exists (select 1 from public.academy_capstones c
                     where c.app_slug = 'gaslift' and c.tier = 'beginner' and c.active
                       and position('"Your well, typed" view' in c.prompt) > 0) then
    raise exception 'hd nodal refused: the W2-W6 batch is not applied on this database; apply it first (/root/w2w6-apply/apply.sh apply --prod)';
  end if;

  if v_s0 = 'old' then
    update public.academy_capstones
       set prompt = 'Six values for the NEMBE-14 outflow, built on the open flow the Associate tier established. The tubing curve is the gravity-plus-friction relation bhp(q) = pWh + 3835 / (1 + q/600) + 0.000238 q^2, with bhp and pWh in psia and q in stb/d, evaluated at a wellhead pressure of 1236 psia at 49 evenly spaced rates from one thousandth of the absolute open flow up to the absolute open flow itself. The open flow is the Associate tier''s, from its composite inflow: reservoir pressure 3450 psia, bubble point 3100 psia and one test of 1200 stb/d at 2790 psia. The gas-lift injection column is a dry gas column of specific gravity 0.72 at 1,225 psia at the tubing head, 8,900 ft measured and 8,300 ft true vertical, from 96 degF to 214 degF, marched in 20 steps. Report: (1) the RATE at the MINIMUM of the tubing curve; (2) the bottomhole pressure AT that minimum; (3) the bottomhole pressure at the LOW RATE end of the curve; (4) the bottomhole pressure at the OPEN FLOW end; (5) the injection-gas pressure at the VALVE depth; and (6) the injection-gas pressure at the MIDPOINT of the column. Traps. Fields 3 and 4 are the two ENDS of the same curve and both must come out ABOVE the reservoir pressure of 3,450 psia, which is the whole point of this well: the column outweighs the reservoir at both ends and the well cannot start itself. A learner who reports a low-rate end below reservoir pressure has evaluated the gravity term at the wrong place. Field 1 is read off the SAMPLED curve at the stated 49 points and not off an analytic minimum, because the sampled minimum is what the engine returns and a finer sampling moves it. The injection column is marched at TWENTY steps and not at the published two-station default; on a gravity-only column the two answers differ by only a fraction of a psi, which is exactly why the difference is easy to miss and why the tier makes you state the step count. Free checks: field 2 must be the smallest bottomhole pressure anywhere on the curve, and both fields 3 and 4 must exceed it; field 1 must fall strictly between the ends of the rate range; and field 6 must sit between the 1,225 psia tubing head pressure and field 5, since a static gas column only gains pressure with depth. On the course panel, the Outflow explorer''s "Your gas column, typed" view takes this injection column as typed (gravity, tubing head pressure, both depths, both temperatures and the step count) and prints the pressures at the bottom of the column (the valve depth) and at its midpoint station to six decimals.'
     where app_slug = 'nodal' and tier = 'intermediate' and active;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'hd nodal refused: nodal/intermediate updated % rows', v_count; end if;
    v_written := v_written + 1;
  end if;
  if (select (md5(prompt) = 'ac000b3efdcbacb24b57d5f0ea1c3639' and fields = '[{"key": "vlp_min_q_stbd", "tol": 0.00064, "unit": "stb/d", "label": "Rate at the curve minimum", "expected": 1285.2338376891341}, {"key": "vlp_min_bhp_psia", "tol": 0.0014, "unit": "psia", "label": "Pressure at the minimum", "expected": 2849.67283735105}, {"key": "vlp_loaded_end_bhp_psia", "tol": 0.0025, "unit": "psia", "label": "Low rate end", "expected": 5046.565087663264}, {"key": "vlp_friction_end_bhp_psia", "tol": 0.0026, "unit": "psia", "label": "Open flow end", "expected": 5277.411341029544}, {"key": "liftgas_valve_pwf_psia", "tol": 0.00076, "unit": "psia", "label": "Injection pressure at depth", "expected": 1516.5314295864096}, {"key": "liftgas_mid_pmf_psia", "tol": 0.00069, "unit": "psia", "label": "Injection pressure at midpoint", "expected": 1373.724371881081}]'::jsonb) from public.academy_capstones where app_slug = 'nodal' and tier = 'intermediate' and active) is not true then
    raise exception 'hd nodal refused: nodal/intermediate does not read back as its HD form';
  end if;

  raise notice 'hd nodal: % of 1 row(s) written, % already applied', v_written, 1 - v_written;
end $$;
